   189	type shimProcStat struct {
   190		ppid   int
   191		zombie bool
   192	}
   193	
   194	func readShimProcStat(pid int) (shimProcStat, error) {
   195		raw, err := os.ReadFile("/proc/" + strconv.Itoa(pid) + "/stat")
   196		if err != nil {
   197			return shimProcStat{}, err
   198		}
   199		text := string(raw)
   200		end := strings.LastIndexByte(text, ')')
   201		if end < 0 {
   202			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   203		}
   204		f := strings.Fields(text[end+1:])
   205		if len(f) < 2 {
   206			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   207		}
   208		ppid, err := strconv.Atoi(f[1])
   209		if err != nil {
   210			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   211		}
   212		return shimProcStat{ppid: ppid, zombie: f[0] == "Z"}, nil
   213	}
