   163	func reviewProcessMarked(pid int, entry []byte) (bool, error) {
   164		environ, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "environ"))
   165		if err != nil {
   166			return false, err
   167		}
