   176	func reviewProcessOwner(pid int) (int, error) {
   177		info, err := os.Stat(filepath.Join("/proc", strconv.Itoa(pid)))
   178		if err != nil {
   179			return 0, err
   180		}
   181		st, ok := info.Sys().(*syscall.Stat_t)
   182		if !ok {
   183			return 0, fmt.Errorf("process %d owner unavailable", pid)
   184		}
   185		return int(st.Uid), nil
   186	}
